import{_ as t}from"./chunks/setting._LF0sekZ.js";import{_ as e,o as r,c as o,a3 as i}from"./chunks/framework.BM_-pWjS.js";const g=JSON.parse('{"title":"評価の伝搬","description":"","frontmatter":{},"headers":[],"relativePath":"ja/rating-spec.md","filePath":"ja/rating-spec.md"}'),n={name:"ja/rating-spec.md"};function d(l,a,s,p,c,h){return r(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="評価の伝搬" tabindex="-1">評価の伝搬 <a class="header-anchor" href="#評価の伝搬" aria-label="Permalink to &quot;評価の伝搬&quot;">​</a></h1><p>グループ化された写真に評価を付けると、その評価はグループ内のすべての写真に伝搬します。</p><h2 id="基本動作" tabindex="-1">基本動作 <a class="header-anchor" href="#基本動作" aria-label="Permalink to &quot;基本動作&quot;">​</a></h2><p>サムネイルグリッドでグループの代表カットに評価を付けた場合、グループに属する全カットに同じ星評価・カラーラベルが書き込まれます。これはバースト撮影やブラケット撮影のように「一連の写真をまとめて採用・却下したい」場面での操作を簡略化するためのデフォルト動作です。</p><h2 id="個別調整" tabindex="-1">個別調整 <a class="header-anchor" href="#個別調整" aria-label="Permalink to &quot;個別調整&quot;">​</a></h2><p>グループ全体への伝搬後、個別のカットだけ評価を変えたい場合は<strong>メタデータバー</strong>から操作します。</p><ol><li>グループの代表カットを選択する</li><li>メタデータバーにグループ内のカット一覧が表示される</li><li>変更したいカットをメタデータバー内で選択し、評価を付ける</li></ol><p>メタデータバーで付けた評価は選択したカット単体にのみ書き込まれ、他のカットには影響しません。</p><h2 id="伝搬のカスタマイズ" tabindex="-1">伝搬のカスタマイズ <a class="header-anchor" href="#伝搬のカスタマイズ" aria-label="Permalink to &quot;伝搬のカスタマイズ&quot;">​</a></h2><p>設定画面の <strong>Rating Propagation</strong> セクションで、ファイル種別をまたいだ伝搬の挙動を変更できます。</p><p><img src="'+t+'" alt="設定画面 - Rating Propagation"></p><p>表の<strong>行</strong>が評価を付けた元の種別、<strong>列</strong>が同じ評価を受け取る種別です。チェックマークは変更不可（自分自身には常に書き込まれる）、トグルで有効・無効を切り替えられます。</p><h2 id="伝搬のタイミング" tabindex="-1">伝搬のタイミング <a class="header-anchor" href="#伝搬のタイミング" aria-label="Permalink to &quot;伝搬のタイミング&quot;">​</a></h2><p>評価の伝搬は操作した瞬間に即時書き込まれます。取り消す場合は <code>⌘Z</code> で元に戻せます。</p><h2 id="xmp-の書き込み先" tabindex="-1">XMP の書き込み先 <a class="header-anchor" href="#xmp-の書き込み先" aria-label="Permalink to &quot;XMP の書き込み先&quot;">​</a></h2><p>グループ内の各カットへの書き込みルールは通常の評価と同じです。</p><table tabindex="0"><thead><tr><th>ファイル種別</th><th>保存先</th></tr></thead><tbody><tr><td>RAW（<code>.arw</code> / <code>.cr3</code> など）</td><td>同名の <code>.xmp</code> サイドカー</td></tr><tr><td>JPEG</td><td>ファイルに直接埋め込み</td></tr></tbody></table>',17)])])}const b=e(n,[["render",d]]);export{g as __pageData,b as default};
